decl:
export interface OpenAIAgentRef {
    name: string;
}

export interface OpenAIApplyPatchCallItem {
    type: "apply_patch_call";
    callId: string;
    status: "in_progress" | "completed";
    operation: OpenAIApplyPatchOperation;
    id?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIApplyPatchCallResultItem {
    type: "apply_patch_call_output";
    callId: string;
    status: "completed" | "failed";
    output?: string;
    id?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIApplyPatchOperation {
    type: "create_file" | "update_file" | "delete_file";
    path: string;
    diff?: string;
    moveTo?: string;
}

export interface OpenAIAssistantMessageItem {
    type?: "message";
    role: "assistant";
    phase?: "commentary" | "final_answer";
    status: "in_progress" | "completed" | "incomplete";
    content: OpenAIContentPart[];
    id?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIComputerCallItem {
    type: "computer_call";
    callId: string;
    status: "in_progress" | "completed" | "incomplete";
    action?: JsonValue;
    actions?: JsonValue;
    id?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIComputerCallResultItem {
    type: "computer_call_result";
    callId: string;
    output: {
        type: "computer_screenshot";
        data: string;
    };
    id?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIFileCitationAnnotation {
    type: "file_citation";
    file_id?: string;
    filename?: string;
    index?: number;
}

export interface OpenAIFunctionCallItem {
    type: "function_call";
    callId: string;
    name: string;
    arguments: string;
    status?: "in_progress" | "completed" | "incomplete";
    id?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIFunctionCallResultItem {
    type: "function_call_result";
    name: string;
    callId: string;
    status: "in_progress" | "completed" | "incomplete";
    output: string | OpenAIToolOutputText | OpenAIToolOutputInputText[];
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIHostError {
    type: "__host_error__";
    code: string;
    message: string;
    usage?: AgUsage;
}

export interface OpenAIHostedToolCallItem {
    type: "hosted_tool_call";
    id?: string;
    name: string;
    arguments?: string;
    status?: string;
    output?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIOutputText {
    type: "output_text";
    text: string;
    annotations?: OpenAIAnnotation[];
}

export interface OpenAIProgramCallItem {
    type: "program";
    callId: string;
    code: string;
    fingerprint: string;
    id?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIProgramCallResultItem {
    type: "program_output";
    callId: string;
    output: string;
    status: "completed" | "incomplete";
    id?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIReasoningItem {
    type: "reasoning";
    id?: string;
    content: OpenAIReasoningTextPart[];
    providerData?: {
        encrypted_content?: string;
        [k: string]: JsonValue | undefined;
    };
}

export interface OpenAIReasoningTextPart {
    type: "input_text";
    text: string;
}

export interface OpenAIRefusal {
    type: "refusal";
    refusal: string;
}

export interface OpenAIShellAction {
    commands: string[];
    timeoutMs?: number;
    maxOutputLength?: number;
}

export interface OpenAIShellCallItem {
    type: "shell_call";
    callId: string;
    status?: "in_progress" | "completed" | "incomplete";
    action: OpenAIShellAction;
    id?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIShellCallOutcome {
    type: "timeout" | "exit";
    exitCode?: number | null;
}

export interface OpenAIShellCallOutputContent {
    stdout: string;
    stderr: string;
    outcome: OpenAIShellCallOutcome;
}

export interface OpenAIShellCallResultItem {
    type: "shell_call_output";
    callId: string;
    status?: "in_progress" | "completed" | "incomplete";
    maxOutputLength?: number;
    output: OpenAIShellCallOutputContent[];
    id?: string;
    caller?: OpenAIToolCaller;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export type OpenAIToolCaller = {
    type: "direct";
} | {
    type: "program";
    callerId: string;
};

export interface OpenAIToolOutputInputText {
    type: "input_text";
    text: string;
}

export interface OpenAIToolOutputText {
    type: "text";
    text: string;
}

export interface OpenAIToolSearchCallItem {
    type: "tool_search_call";
    id?: string;
    call_id?: string | null;
    callId?: string | null;
    execution?: "client" | "server";
    arguments?: JsonValue;
    status?: string;
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIToolSearchOutputItem {
    type: "tool_search_output";
    id?: string;
    toolSearchAgentName?: string;
    call_id?: string | null;
    callId?: string | null;
    execution?: "client" | "server";
    status?: string;
    tools: {
        [k: string]: JsonValue;
    }[];
    providerData?: {
        [k: string]: JsonValue;
    };
}

export interface OpenAIUrlCitationAnnotation {
    type: "url_citation";
    url: string;
    title?: string;
    start_index?: number;
    end_index?: number;
}

export interface OpenaiNormalizerOptions {
    invokeId?: string;
    threadId?: string;
}
